// Frischt Microsoft-Zugaenge auf, bevor sie ablaufen. Ohne diesen Lauf merkt
// niemand etwas, solange jemand aktiv fragt (der Skill erneuert dann selbst),
// aber Erinnerungen und naechtliche Zusammenfassungen laufen ins Leere.
// Zusaetzlich haelt er die 90-Tage-Frist offen: ein Zugang, der drei Monate
// nicht benutzt wird, verfaellt bei Microsoft endgueltig.

const SUPABASE_URL = '{{SUPABASE_URL}}';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_KEY}}';
const pg = { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY, 'Content-Type': 'application/json' };

const credRows = await helpers.httpRequest({
  method: 'GET',
  url: SUPABASE_URL + '/rest/v1/template_credentials?template_id=eq.microsoft&select=cred_key,cred_value',
  headers: pg, json: true
});
const cred = {};
for (const c of (credRows || [])) cred[c.cred_key] = c.cred_value;
if (!cred.token_key || !cred.client_id) return [{ json: { result: 'Microsoft ist nicht eingerichtet, nichts zu tun.' } }];

// Faellig: laeuft in den naechsten 25 Minuten ab, ODER wurde seit 50 Tagen nicht
// erneuert (dann ist die 90-Tage-Frist in Sicht).
const faellig = await helpers.httpRequest({
  method: 'GET',
  url: SUPABASE_URL + "/rest/v1/user_oauth_tokens?provider=eq.microsoft&status=eq.connected" +
       "&or=(expires_at.lt." + new Date(Date.now() + 25 * 60000).toISOString() +
       ",last_refresh_at.lt." + new Date(Date.now() - 50 * 864e5).toISOString() + ")" +
       "&select=user_key,account_id,scopes",
  headers: pg, json: true
});

if (!faellig || !faellig.length) return [{ json: { result: 'Keine Zugaenge faellig.' } }];

const ok = [], kaputt = [];
for (const row of faellig) {
  let tokRow;
  try {
    const rows = await helpers.httpRequest({
      method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/get_user_token', headers: pg, json: true,
      body: JSON.stringify({ p_user_key: row.user_key, p_provider: 'microsoft', p_key: cred.token_key, p_account_id: row.account_id || '' })
    });
    tokRow = rows && rows[0];
  } catch (e) { kaputt.push(row.user_key + ' (nicht lesbar)'); continue; }
  if (!tokRow || !tokRow.refresh_token) {
    await helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/mark_user_token', headers: pg,
      body: JSON.stringify({ p_user_key: row.user_key, p_provider: 'microsoft', p_status: 'reconnect_required', p_detail: 'kein refresh_token' }) });
    kaputt.push(row.user_key + ' (kein refresh_token)');
    continue;
  }
  try {
    const tok = await helpers.httpRequest({
      method: 'POST',
      url: 'https://login.microsoftonline.com/' + encodeURIComponent(cred.tenant_id) + '/oauth2/v2.0/token',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, json: true,
      body: 'client_id=' + encodeURIComponent(cred.client_id) +
            '&client_secret=' + encodeURIComponent(cred.client_secret) +
            '&refresh_token=' + encodeURIComponent(tokRow.refresh_token) +
            '&grant_type=refresh_token&scope=' + encodeURIComponent(row.scopes || tokRow.scopes || 'openid profile offline_access')
    });
    await helpers.httpRequest({
      method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/upsert_user_token', headers: pg,
      body: JSON.stringify({
        p_user_key: row.user_key, p_provider: 'microsoft', p_key: cred.token_key,
        p_access_token: tok.access_token, p_refresh_token: tok.refresh_token || '',
        p_expires_at: new Date(Date.now() + ((tok.expires_in || 3600) * 1000)).toISOString(),
        p_scopes: tok.scope || row.scopes || null, p_account_id: row.account_id || ''
      })
    });
    ok.push(row.user_key);
  } catch (e) {
    const body = (e && e.response && e.response.body) ? JSON.stringify(e.response.body) : String(e.message || e);
    const code = (body.match(/AADSTS\d+/) || ['unbekannt'])[0];
    await helpers.httpRequest({ method: 'POST', url: SUPABASE_URL + '/rest/v1/rpc/mark_user_token', headers: pg,
      body: JSON.stringify({ p_user_key: row.user_key, p_provider: 'microsoft', p_status: 'reconnect_required', p_detail: code }) });
    kaputt.push(row.user_key + ' (' + code + ')');
  }
}

return [{ json: { result: 'Erneuert: ' + (ok.join(', ') || 'keine') + (kaputt.length ? ' | Muss neu verbinden: ' + kaputt.join(', ') : '') } }];
